    const grid = Array.from({ length: row }, () => new Array(col).fill(0));
    for (let i = 0; i < day; i++) {
      grid[cells[i][0] - 1][cells[i][1] - 1] = 1;
    }
    const q = [];
    for (let c = 0; c < col; c++) {
      if (!grid[0][c]) {
        q.push([0, c]);
        grid[0][c] = 1;
      }
    }
    let head = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (head < q.length) {
      const [r, c] = q[head++];
      if (r === row - 1) return true;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < row && nc >= 0 && nc < col && !grid[nr][nc]) {
          grid[nr][nc] = 1;
          q.push([nr, nc]);
        }
      }
    }
    return false;
  };

  let low = 1, high = cells.length, ans = 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    if (canCross(mid)) {
      ans = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return ans;
};
